/// <summary>
/// PaffH 22.11.24
/// </summary>
/// <param name = "_itemPictureName">NDXBTItemPicture</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXProdIdentPicture</returns>
public static NDXProdIdentPicture find(NDXBTItemPicture _itemPictureName, boolean _forUpdate = false)
{
    NDXProdIdentPicture nDXProdIdentPicture;
    nDXProdIdentPicture.selectForUpdate(_forUpdate);
    select firstonly nDXProdIdentPicture 
        where nDXProdIdentPicture.ItemPictureName == _itemPictureName;
    return nDXProdIdentPicture;
}

/// <summary>
/// PaffH 22.11.24
/// </summary>
/// <param name = "_itemPictureName">NDXBTItemPicture</param>
/// <param name = "_insert">boolean</param>
/// <returns>NDXProdIdentPicture</returns>
public static NDXProdIdentPicture findOrCreate(NDXBTItemPicture _itemPictureName, boolean _insert = false)
{
    NDXProdIdentPicture nDXProdIdentPicture;
    nDXProdIdentPicture = NDXProdIdentPicture::find(_itemPictureName, true);
    if (!nDXProdIdentPicture)
    {
        nDXProdIdentPicture.ItemPictureName = _itemPictureName;
        if (_insert)
        {
            nDXProdIdentPicture.insert();
        }
    }
    return nDXProdIdentPicture;
}

/// <summary>
/// PaffH 22.11.24
/// </summary>        
public static void updateFromNDXProdIdentPictureItemIdMapping()
{
    NDXProdIdentPictureItemIdMapping nDXProdIdentPictureItemIdMapping;
    while select crosscompany nDXProdIdentPictureItemIdMapping
        group by ItemPictureName
    {
        NDXProdIdentPicture::findOrCreate(nDXProdIdentPictureItemIdMapping.ItemPictureName, true);
    }
}

/// <summary>
/// PaffH 30.12.24
/// </summary>
/// <param name = "_itemPicture">NDXBTItemPicture</param>
/// <returns>changedCounter</returns>
public static Counter checkNumberOfItemAssignments(NDXBTItemPicture _itemPicture = '')
{
    Counter changedCounter = 0;
    NDXProdIdentPicture nDXProdIdentPicture;
    NDXProdIdentPicture nDXProdIdentPictureGrp;
    NDXProdIdentPictureItemIdMapping nDXProdIdentPictureItemIdMapping;
    Query q = new Query();
    QueryBuildDataSource qbdsNDXProdIdentPictureGrp = q.addDataSource(tableNum(NDXProdIdentPicture));
    if (_itemPicture)
    {
        qbdsNDXProdIdentPictureGrp.addRange(fieldNum(NDXProdIdentPicture, ItemPictureName)).value(_itemPicture);
    }
    QueryBuildDataSource qbdsnDXProdIdentPictureItemIdMapping = qbdsNDXProdIdentPictureGrp.addDataSource(tableNum(NDXProdIdentPictureItemIdMapping));
    qbdsnDXProdIdentPictureItemIdMapping.relations(true);
    qbdsNDXProdIdentPictureGrp.addGroupByField(fieldNum(NDXProdIdentPicture, ItemPictureName));
    qbdsnDXProdIdentPictureItemIdMapping.addSelectionField(fieldNum(NDXProdIdentPictureItemIdMapping, RecId), SelectionField::Count);
    QueryRun qr = new QueryRun(q);
    ttsbegin;
    while (qr.next())
    {
        nDXProdIdentPictureGrp = qr.get(tableNum(NDXProdIdentPicture));
        nDXProdIdentPictureItemIdMapping = qr.get(tableNum(NDXProdIdentPictureItemIdMapping));
        nDXProdIdentPicture = NDXProdIdentPicture::find(nDXProdIdentPictureGrp.ItemPictureName, true);
        if (nDXProdIdentPicture.RecId > 0 && nDXProdIdentPicture.NumberOfItemAssignments != nDXProdIdentPictureItemIdMapping.RecId)
        {
            nDXProdIdentPicture.NumberOfItemAssignments = nDXProdIdentPictureItemIdMapping.RecId;
            nDXProdIdentPicture.update();
            ++changedCounter;
        }
    }
    ttscommit;
    return changedCounter;
}

/// <summary>
/// PaffH 04.01.25
/// </summary>
public void initValue()
{
    super();

    NDXProdIdentPicture NDXProdIdentPicture;
    select firstonly PictureId from nDXProdIdentPicture order by PictureId desc;
    this.PictureId = nDXProdIdentPicture.PictureId + 1;
}
